mapper.select:
SELECT
lifecycle_event_id,
lifecycle_scenario_id,
event_order,
target_date,
JSON_UNQUOTE(
JSON_EXTRACT(survey_data, '$.vehicleName')
) AS vehicle_name,

JSON_UNQUOTE(
JSON_EXTRACT(survey_data, '$.vehicleModel')
) AS vehicle_model,

JSON_UNQUOTE(
JSON_EXTRACT(survey_data, '$.vehicleCondition')
) AS vehicle_condition,

CAST(
JSON_UNQUOTE(
JSON_EXTRACT(survey_data, '$.annualMileageKm')
) AS UNSIGNED
) AS annual_mileage_km,

CAST(
JSON_UNQUOTE(
JSON_EXTRACT(survey_data, '$.vehiclePrice')
) AS DECIMAL(19,2)
) AS vehicle_price,

CAST(
JSON_UNQUOTE(
JSON_EXTRACT(survey_data, '$.cashPaymentAmount')
) AS DECIMAL(19,2)
) AS cash_payment_amount,

CAST(
JSON_UNQUOTE(
JSON_EXTRACT(survey_data, '$.loanAmount')
) AS DECIMAL(19,2)
) AS loan_amount,

CAST(
JSON_UNQUOTE(
JSON_EXTRACT(survey_data, '$.loanPeriodMonths')
) AS UNSIGNED
) AS loan_period_months,

CAST(
JSON_UNQUOTE(
JSON_EXTRACT(survey_data, '$.monthlyMaintenanceCost')
) AS DECIMAL(19,2)
) AS monthly_maintenance_cost,

created_at,
updated_at

FROM lifecycle_event

WHERE lifecycle_event_id = #{lifecycleEventId}
AND event_type = 'VEHICLE_PURCHASE'

SELECT
lifecycle_event_id,
lifecycle_scenario_id,
event_order,
target_date,
lifestyle_level,

JSON_UNQUOTE(
JSON_EXTRACT(survey_data, '$.regionSido')
) AS region_sido,

JSON_UNQUOTE(
JSON_EXTRACT(survey_data, '$.regionSigungu')
) AS region_sigungu,

JSON_UNQUOTE(
JSON_EXTRACT(survey_data, '$.housingType')
) AS housing_type,

CAST(
JSON_UNQUOTE(
JSON_EXTRACT(survey_data, '$.desiredArea')
) AS DECIMAL(10,2)
) AS desired_area,

CAST(
JSON_UNQUOTE(
JSON_EXTRACT(survey_data, '$.desiredPurchasePrice')
) AS DECIMAL(19,2)
) AS desired_purchase_price,

CAST(
JSON_UNQUOTE(
JSON_EXTRACT(survey_data, '$.ownFundAmount')
) AS DECIMAL(19,2)
) AS own_fund_amount,

CAST(
JSON_UNQUOTE(
JSON_EXTRACT(survey_data, '$.loanPeriodMonths')
) AS UNSIGNED
) AS loan_period_months,

JSON_UNQUOTE(
JSON_EXTRACT(survey_data, '$.repaymentType')
) AS repayment_type,

created_at,
updated_at

FROM lifecycle_event

WHERE lifecycle_event_id = #{lifecycleEventId}
AND event_type = 'HOME_PURCHASE'

SELECT COALESCE(MAX(event_order), 0) + 1
FROM lifecycle_event
WHERE lifecycle_scenario_id = #{scenarioId}

SELECT lifecycle_event_id
FROM lifecycle_event
WHERE lifecycle_scenario_id = #{scenarioId}
  AND event_type = #{eventType}
ORDER BY lifecycle_event_id DESC
LIMIT 1
